const formats={group:'Путешествия в небольшой компании по заранее подготовленным маршрутам. Вместе исследуем города, знакомимся с культурой, пробуем местную кухню и открываем интересные места.',expedition:'Необычные маршруты, новые города и более насыщенная программа — для тех, кто хочет увидеть страну с другой стороны.',private:'Персональный маршрут с учётом пожеланий, бюджета и интересов — для одного человека, пары, семьи или друзей.'};
const tours=[
 {id:'korea-japan',category:'group',title:'Корея + Япония',route:'Сеул — Пусан — Осака — Киото — Нара — Токио',dates:'20–29 марта 2027',days:'10 дней',price:'от $2 850',places:'6 мест',status:'Открыт набор',image:'https://images.unsplash.com/photo-1538485399081-7191377e8241?auto=format&fit=crop&w=1200&q=85',desc:'Две страны в одном путешествии: динамичный Сеул, морской Пусан и весенняя Япония.',program:['Прибытие в Сеул и знакомство','Дворцы и современный Сеул','Поезд в Пусан, побережье','Рынки и храмы Пусана','Перелёт в Осаку','Киото: традиционные кварталы','Нара и её парки','Переезд в Токио','Токио: контрасты мегаполиса','Свободное утро и вылет']},
 {id:'japan-korea',category:'group',title:'Япония + Корея',route:'Токио — Киото — Осака — Нара — Пусан — Сеул',dates:'12–21 апреля 2027',days:'10 дней',price:'от $2 950',places:'3 места',status:'Осталось несколько мест',image:'https://images.unsplash.com/photo-1528360983277-13d401cdc186?auto=format&fit=crop&w=1200&q=85',desc:'От токийских неоновых кварталов до старых улочек Киото и ритма современной Кореи.',program:['Встреча в Токио','Главные районы столицы','Камакура у океана','Скоростной поезд в Киото','Храмы и чайные кварталы','Осака и гастрономия','Нара, перелёт в Пусан','Побережье Пусана','Сеул: дворцы и дизайн','Финальный день и вылет']},
 {id:'other-japan',category:'expedition',title:'Другая Япония',route:'Канадзава — Такаяма — Коясан — Наосима',dates:'8–20 мая 2027',days:'13 дней',price:'от $3 650',places:'Скоро',status:'Скоро анонс',image:'https://images.unsplash.com/photo-1526481280695-3c687fd643ed?auto=format&fit=crop&w=1200&q=85',desc:'Меньше очевидных маршрутов: горные города, остров искусства и ночь в буддийском монастыре.',program:['Встреча в Токио','Поезд в Канадзаву','Сады и самурайский квартал','Горная деревня Сиракава-го','Такаяма','Переезд в Киото','Свободный день','Храмовая гора Коясан','Поезд к морю','Остров Наосима','Архитектура и музеи','Возвращение в Осаку','Вылет домой']},
 {id:'private-asia',category:'private',title:'Ваша Азия',route:'Маршрут создаём вместе',dates:'В удобные даты',days:'от 7 дней',price:'по запросу',places:'Индивидуально',status:'Принимаем заявки',image:'https://images.unsplash.com/photo-1493780474015-ba834fd0ce2f?auto=format&fit=crop&w=1200&q=85',desc:'Личное путешествие для пары, семьи или друзей с маршрутом под ваши интересы.',program:['Знакомство и бриф','Проектирование маршрута','Бронирования и подготовка','Ваше путешествие с поддержкой']}
];
const departures=[{month:'Март 2027',items:[{date:'20–29 марта',tour:'Корея + Япония',status:'Открыт набор',id:'korea-japan'}]},{month:'Апрель 2027',items:[{date:'3–12 апреля',tour:'Корея + Япония',status:'Открыт набор',id:'korea-japan'},{date:'12–21 апреля',tour:'Япония + Корея',status:'Мало мест',id:'japan-korea',few:true}]},{month:'Май 2027',items:[{date:'8–20 мая',tour:'Другая Япония',status:'Скоро анонс',id:'other-japan'}]}];
const faqs=[['Кто сопровождает группу?','Часть путешествий Гаухар сопровождает лично. Также с группами работают групп-лидеры и местные специалисты. В отдельных программах предусмотрены услуги местных экскурсоводов.'],['Какой формат размещения?','Обычно участники размещаются по два человека в номере. Если вы путешествуете один, мы можем подобрать соседа. Одноместное размещение возможно за дополнительную плату.'],['Можно ли поехать одному?','Конечно. Многие участники присоединяются самостоятельно — групповой формат помогает легко познакомиться с новыми людьми.'],['Как оплатить путешествие?','Можно оплатить полностью либо несколькими платежами по согласованному графику. Все условия и окончательная сумма фиксируются до оплаты.'],['Нужно ли самостоятельно оформлять визу?','Мы предоставляем список документов и сопровождаем процесс оформления визы в рамках выбранного пакета. Решение о выдаче принимает консульство.'],['Что делать, если я не смогу поехать?','Условия отмены зависят от даты отказа и уже оплаченных услуг. Подробные правила указываются в договоре до бронирования.']];
const grid=document.querySelector('#trip-grid'),desc=document.querySelector('#format-description');
function renderTrips(category){desc.textContent=formats[category];const list=tours.filter(t=>t.category===category);grid.innerHTML=list.map(t=>`<article class="trip-card" data-id="${t.id}" tabindex="0"><div class="trip-image" style="background-image:url('${t.image}')"><span class="trip-status">${t.status}</span></div><div class="trip-card-body"><p class="trip-meta">${t.dates} · ${t.days}</p><h3>${t.title}</h3><p class="trip-route">${t.route}</p><div class="trip-price"><strong>${t.price}</strong><span>${t.places} →</span></div></div></article>`).join('');document.querySelectorAll('.trip-card').forEach(card=>{card.onclick=()=>openTour(card.dataset.id);card.onkeydown=e=>{if(e.key==='Enter')openTour(card.dataset.id)}})}
document.querySelectorAll('.format-tab').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.format-tab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderTrips(btn.dataset.category)});renderTrips('group');
document.querySelector('#calendar-list').innerHTML=departures.map(m=>`<div class="month-row"><div class="month-name">${m.month}</div><div>${m.items.map(i=>`<div class="departure" data-id="${i.id}"><span class="departure-date">${i.date}</span><strong class="departure-title">${i.tour}</strong><span class="pill ${i.few?'few':''}">${i.status}</span><span>↗</span></div>`).join('')}</div></div>`).join('');document.querySelectorAll('.departure').forEach(x=>x.onclick=()=>openTour(x.dataset.id));
document.querySelector('#faq-list').innerHTML=faqs.map(([q,a])=>`<div class="faq-item"><button class="faq-question"><span class="qtext">${q}</span><span>+</span></button><div class="faq-answer"><p>${a}</p></div></div>`).join('');document.querySelectorAll('.faq-question').forEach(b=>b.onclick=()=>{const item=b.parentNode;item.classList.toggle('open');b.lastElementChild.textContent=item.classList.contains('open')?'−':'+'});
const modal=document.querySelector('#tour-modal');function openTour(id){const t=tours.find(x=>x.id===id);document.querySelector('#tour-detail').innerHTML=`<div class="detail-hero" style="background-image:url('${t.image}')"><div><p class="eyebrow light">${t.status}</p><h2>${t.title}</h2><p>${t.route}</p></div></div><div class="detail-content"><p>${t.desc}</p><div class="detail-summary"><div><span>Даты</span><strong>${t.dates}</strong></div><div><span>Длительность</span><strong>${t.days}</strong></div><div><span>Стоимость</span><strong>${t.price}</strong></div><div><span>Места</span><strong>${t.places}</strong></div></div><h3>Программа путешествия</h3>${t.program.map((d,i)=>`<div class="day"><strong>День ${i+1} — ${d}</strong><p>Детали дня, активности и рекомендации будут уточнены перед поездкой.</p></div>`).join('')}<div class="detail-lists"><div><h3>В стоимость входит</h3><ul><li>Проживание по программе</li><li>Трансферы между городами</li><li>Сопровождение групп-лидера</li><li>Организационная поддержка</li></ul></div><div><h3>Оплачивается отдельно</h3><ul><li>Международный перелёт</li><li>Питание вне программы</li><li>Личные расходы</li><li>Страховка и виза</li></ul></div></div><button class="button button-dark detail-cta" onclick="chooseTour('${t.id}')">Оставить заявку <span>↗</span></button></div>`;modal.showModal();document.body.style.overflow='hidden'}
document.querySelector('.modal-close').onclick=()=>modal.close();modal.addEventListener('close',()=>document.body.style.overflow='');modal.onclick=e=>{if(e.target===modal)modal.close()};
const tourSelect=document.querySelector('#tour-select'),dateSelect=document.querySelector('#date-select');tourSelect.innerHTML=tours.map(t=>`<option value="${t.id}">${t.title}</option>`).join('');function updateDates(){const t=tours.find(x=>x.id===tourSelect.value);dateSelect.innerHTML=`<option>${t.dates}</option>`}tourSelect.onchange=updateDates;updateDates();window.chooseTour=id=>{modal.close();tourSelect.value=id;updateDates();document.querySelector('#contact').scrollIntoView({behavior:'smooth'})};
document.querySelector('#lead-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const leads=JSON.parse(localStorage.getItem('visaLandLeads')||'[]');leads.push({...data,createdAt:new Date().toISOString()});localStorage.setItem('visaLandLeads',JSON.stringify(leads));document.querySelector('#form-status').textContent='Спасибо! Заявка сохранена. Мы свяжемся с вами в ближайшее время.';e.target.reset();updateDates()};
const header=document.querySelector('#header');addEventListener('scroll',()=>header.classList.toggle('scrolled',scrollY>40));const toggle=document.querySelector('.menu-toggle'),menu=document.querySelector('.mobile-menu');toggle.onclick=()=>{const open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',open);menu.setAttribute('aria-hidden',!open)};menu.querySelectorAll('a').forEach(a=>a.onclick=()=>{menu.classList.remove('open');toggle.setAttribute('aria-expanded','false')});
